const { createHash } = require("crypto");
const target = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const bases = [
  "quarterly report", "quarterly-report", "quarterly_report", "quarterlyreport",
  "quarterly  report", "quarterly report.", "quarterly report?", "quarterly report!",
  "quarterly report,", "quarterly report;", "quarterly report:"]
  .flatMap((b) => [b, b + " ", " " + b, b + "\n", b + "\t"]);

const cores = [];
const pre = ["", " ", "-", "_", "\t", "\n", ".", "|", "/", "*", "~", "^", "<", ">", "[", "]", "(", ")", "{", "}", "=", "+", "%", "#", "&", "@", "!", "?", ",", ";", ":", "’", "‘", "“", "”", "'", '"', "·", "•", "§", "¶", "†", "‡"];
const coreC = ["_2026", "__2026", "_ 2026", "_20260", "_20266", "_2027", "_2O26", "_2026.", "_2026-", "_2026_"];
for (const p of pre) for (const c of coreC) cores.push(p + c);

const sfxs = ["", " ", "\t", "\n", "\r", "\u00a0", "_", "-", ".", "\u200b", "\ufeff", "\u00ad", "\u2009", "\u200a", "\u200b", "\u2060"];
let found = 0, n = 0;
for (const b of bases) for (const c of cores) for (const s of sfxs) {
  n++;
  const str = b + c + s;
  if (!str.includes("_2026")) continue;
  if (createHash("sha256").update(str, "utf8").digest("hex") === target) {
    console.log("MATCH", JSON.stringify(str)); found++;
  }
}
console.log("n", n, "found", found);

